using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using RouteTrackerCommander;
class QueueTests {
 class PumpContext:SynchronizationContext {readonly Queue<Action> pending=new Queue<Action>();public override void Post(SendOrPostCallback f,object v){pending.Enqueue(()=>f(v));}public void Drain(){while(pending.Count>0)pending.Dequeue()();}}
 static int checks;static void Assert(bool ok,string msg){checks++;if(!ok)throw new Exception(msg);}
 static int Main(){try{var pump=new PumpContext();SynchronizationContext.SetSynchronizationContext(pump);var q=new LatestRefreshQueue<string>();var gate=new TaskCompletionSource<bool>();var started=new List<string>();var published=new List<string>();Func<string,int,Task> work=async(s,r)=>{started.Add(s);await gate.Task;if(q.IsCurrent(r))published.Add(s);};q.Request("old",work);q.Request("middle",work);q.Request("latest",work);Assert(started.Count==1,"Only one worker in flight");gate.SetResult(true);pump.Drain();Assert(String.Join(",",started)=="old,latest","Intermediate requests coalesced");Assert(String.Join(",",published)=="latest","Stale result rejected");Assert(q.Completed==2,"Work completed without overlap");var nextGate=new TaskCompletionSource<bool>();q.Request("cancelled",async(s,r)=>{await nextGate.Task;if(q.IsCurrent(r))published.Add(s);});q.CancelPending();nextGate.SetResult(true);pump.Drain();Assert(!published.Contains("cancelled"),"Cancelling invalidates active result");q.Request(null,(s,r)=>{Assert(s==null,"Null system accepted to clear state");return Task.CompletedTask;});q.Request("failure",(s,r)=>Task.FromException(new Exception("Expected test error")));q.Request("recovery",(s,r)=>{published.Add(s);return Task.CompletedTask;});Assert(published.Contains("recovery"),"Queue recovers after failure");var lastGate=new TaskCompletionSource<bool>();q.Request("closed",async(s,r)=>{await lastGate.Task;if(q.IsCurrent(r))published.Add(s);});q.Stop();q.Request("after close",work);lastGate.SetResult(true);pump.Drain();Assert(!published.Contains("closed"),"Closing rejects running result");Assert(!started.Contains("after close"),"Closed queue rejects new requests");Console.WriteLine("PASS "+checks+" asynchronous queue assertions");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}